SELECT site_number,min(trading_date),max(trading_date),count(*),count(DISTINCT stock_code) codes FROM source_product_sale_fact WHERE superseded_at IS NULL GROUP BY 1 ORDER BY 1;
SELECT w.source_record_ref,w.wastage_date,w.product_name_key,w.quantity,w.source_unit_cost,w.unit,w.unit_size,w.recipe_id,w.reason,w.supplier_name FROM resolved_classified_wastage w WHERE w.sales_nature='UNKNOWN' AND w.wastage_date BETWEEN '2026-10-26' AND '2026-11-01' ORDER BY w.source_record_ref;
SELECT s.product_name_key,sum(abs(s.amount)) exposure,string_agg(DISTINCT c.source_product_ref,' | ') identities,string_agg(DISTINCT c.stock_code,' | ') codes FROM resolved_product_sales s JOIN canonical_product_sales c ON c.product_name_key=s.product_name_key AND c.trading_date=s.trading_date AND c.source_system=s.authoritative_source AND c.superseded_at IS NULL WHERE s.trading_date BETWEEN '2026-10-26' AND '2026-11-01' GROUP BY 1 ORDER BY 2 DESC LIMIT 100;
SELECT r.fetcher_identity,r.source_record_ref,r.fetched_at,(convert_from(r.payload_bytes,'UTF8')::jsonb)->'data'->0->'siteNumber' first_site,(convert_from(r.payload_bytes,'UTF8')::jsonb)->'data'->0->'stockCode' first_code FROM raw_record r WHERE r.source_system='CTB' AND r.fetcher_identity='ctb-revenue' AND r.source_record_ref IN ('sale-items:2026-07-28','sale-items:2026-07-30','sale-items:2026-10-26') ORDER BY r.fetched_at DESC LIMIT 12;
